<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require BASE_PATH.'/app/AdminUi.php';$user=Auth::requireLogin();Auth::requirePermission('companies.manage');$pdo=Database::connection();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){Security::verifyCsrf();try{$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$slug=strtolower(trim($_POST['slug']??''));$type=in_array($_POST['company_type']??'transport',['transport','agent'],true)?$_POST['company_type']:'transport';$status=in_array($_POST['status']??'active',['active','hidden','suspended'],true)?$_POST['status']:'active';if(mb_strlen($name)<2||!preg_match('/^[a-z0-9-]{2,190}$/',$slug))throw new RuntimeException('أدخل اسم الشركة ومعرّفاً لاتينياً صالحاً.');$logo=upload_image_file('logo','company-logo');$cover=upload_image_file('cover','company-cover');$oldLogo=$oldCover=null;if($id){$old=$pdo->prepare('SELECT logo_path,cover_path FROM companies WHERE id=?');$old->execute([$id]);$oldRow=$old->fetch();if(!$oldRow)throw new RuntimeException('الشركة غير موجودة.');$oldLogo=$oldRow['logo_path'];$oldCover=$oldRow['cover_path'];}$logo=$logo??$oldLogo;$cover=$cover??$oldCover;$data=[$name,$slug,$type,$logo,$cover,trim($_POST['description']??''),trim($_POST['phone']??''),trim($_POST['whatsapp']??''),$status];if($id){$data[]=$id;$pdo->prepare('UPDATE companies SET name=?,slug=?,company_type=?,logo_path=?,cover_path=?,description=?,phone=?,whatsapp=?,status=? WHERE id=?')->execute($data);admin_log($pdo,$user,'company.updated','company',$id,'تعديل بيانات الشركة');}else{$pdo->prepare('INSERT INTO companies(name,slug,company_type,description,phone,whatsapp,status) VALUES(?,?,?,?,?,?,?)')->execute($data);$id=(int)$pdo->lastInsertId();admin_log($pdo,$user,'company.created','company',$id,'إضافة شركة');}redirect('/admin/companies.php?saved=1');}catch(Throwable $e){$error=$e->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM companies WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}$rows=$pdo->query('SELECT id,name,slug,company_type,logo_path,status,phone,whatsapp FROM companies ORDER BY id DESC')->fetchAll();admin_page_start('إدارة شركات النقل والوكلاء',$user);if($error)echo '<p class="notice danger">'.e($error).'</p>';if(isset($_GET['saved']))echo '<p class="notice">تم حفظ الشركة.</p>';$v=fn($k)=>e($edit[$k]??'');echo '<section class="panel"><h2>'.($edit?'تعديل الشركة':'إضافة شركة').'</h2><form method="post" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="_csrf" value="'.e(Security::csrf()).'"><input type="hidden" name="id" value="'.(int)($edit['id']??0).'"><label>اسم الشركة<input name="name" required value="'.$v('name').'"></label><label>المعرّف اللاتيني<input name="slug" pattern="[a-z0-9-]{2,190}" required value="'.$v('slug').'"></label><label>النوع<select name="company_type"><option value="transport">شركة نقل</option><option value="agent" '.(($edit['company_type']??'')==='agent'?'selected':'').'>وكيل</option></select></label><label>شعار الشركة<input type="file" name="logo" accept="image/png,image/jpeg,image/webp"></label><label>صورة غلاف الشركة<input type="file" name="cover" accept="image/png,image/jpeg,image/webp"></label><label>الهاتف<input name="phone" value="'.$v('phone').'"></label><label>واتساب<input name="whatsapp" value="'.$v('whatsapp').'"></label><label>الحالة<select name="status">';foreach(['active'=>'نشطة','hidden'=>'مخفية','suspended'=>'موقوفة'] as $k=>$label)echo '<option value="'.$k.'" '.(($edit['status']??'active')===$k?'selected':'').'>'.$label.'</option>';echo '</select></label><label class="wide">الوصف<textarea name="description">'. $v('description').'</textarea></label>'.(!empty($edit['logo_path'])?'<div class="wide">الشعار الحالي<br><img src="'.e($edit['logo_path']).'" alt="شعار الشركة" style="max-width:130px;max-height:80px;object-fit:contain"></div>':'').(!empty($edit['cover_path'])?'<div class="wide">الغلاف الحالي<br><img src="'.e($edit['cover_path']).'" alt="غلاف الشركة" style="max-width:260px;max-height:100px;object-fit:cover"></div>':'').'<button class="btn btn-primary">حفظ الشركة</button>'.($edit?'<a class="admin-link" href="/admin/companies.php">إلغاء</a>':'').'</form></section><section class="panel"><table><thead><tr><th>الشركة</th><th>المعرّف</th><th>النوع</th><th>الهاتف</th><th>الحالة</th><th></th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.(!empty($r['logo_path'])?'<img src="'.e($r['logo_path']).'" alt="" style="width:38px;height:38px;object-fit:contain;vertical-align:middle;margin-left:8px">':'').e($r['name']).'</td><td>'.e($r['slug']).'</td><td>'.e($r['company_type']).'</td><td>'.e($r['phone']).'</td><td>'.e($r['status']).'</td><td><a class="admin-link" href="/admin/companies.php?edit='.(int)$r['id'].'">تعديل</a></td></tr>';echo '</tbody></table></section>';admin_page_end();
